lookup.day_rate:
// 人社部发〔2008〕3号: 月计薪天数 (365 − 104) ÷ 12 = 21.75. A paid day leaves out rest days, and no statute sets another rule for an incomplete month, so proration_basis is WORKING_DAYS.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const amount = Number(get(terms, 'rate.amount', 0));
const hours = ctx.lookup.daily_hours;
if (unit === 'DAILY') return amount;
if (unit === 'HOURLY' || unit === 'PIECE') return amount * hours;
const fixed = ctx.lookup.day_rate_allowances.reduce(
	(total, code) => total + Number(get(terms, `allowances.${code}.amount`, 0)),
	0
);
return (amount + fixed) / ctx.lookup.monthly_divisor;
